    """Read the needed files (catalogue first), then parse them in order."""
    if not os.path.isdir(req.directory):
        raise FileProblem("%s: not a directory" % req.directory)
    needed = FILES_NEEDED[req.command]
    texts = {}
    for name in needed:
        texts[name] = read_text(req.directory, name, name == CATALOG)
    catalog = parse_file(CATALOG, parse_catalog, texts[CATALOG])
    movements = orders = None
    if MOVEMENTS in texts:
        movements = parse_file(MOVEMENTS, parse_movements, texts[MOVEMENTS], catalog)
    if ORDERS in texts:
        orders = parse_file(ORDERS, parse_orders, texts[ORDERS], catalog)
    return catalog, movements, orders


